"//! Cyclic XOR de-scrambling and keystream application engine.
//!
//! Provides zero-allocation in-place de-scrambling (`descramble_in_place`), destination-slice
//! de-scrambling (`descramble_slice`), and allocating vector de-scrambling (`descramble_to_vec`)
//! for scrambled DJI record payloads.

use crate::crypto::crc64::derive_key;
use crate::error::FlightReaderError;

/// De-scrambles (or scrambles) `buf` in-place by cyclically applying the 8-byte `key`.
///
/// Because XOR is an involutive operation ($A \oplus K \oplus K = A$), this function
/// is self-inverse: applying it twice with the same key restores the original bytes.
///
/// Each byte `buf[i]` is mutated as `buf[i] ^= key[i % 8]`.
pub fn descramble_in_place(buf: &mut [u8], key: [u8; 8]) {
    for (i, b) in buf.iter_mut().enumerate() {
        *b ^= key[i % 8];
    }
}

/// De-scrambles (or scrambles) `src` into destination buffer `dst` using the cyclic 8-byte `key`.
///
/// Returns `Ok(())` on success.
///
/// # Errors
///
/// Returns [`FlightReaderError::BufferOverflow`] if `dst.len() < src.len()`.
pub fn descramble_slice(src: &[u8], dst: &mut [u8], key: [u8; 8]) -> Result<(), FlightReaderError> {
    if dst.len() < src.len() {
        return Err(FlightReaderError::BufferOverflow {
            required: src.len(),
            capacity: dst.len(),
        });
    }

    for (i, (&s, d)) in src.iter().zip(dst.iter_mut()).enumerate() {
        *d = s ^ key[i % 8];
    }

    Ok(())
}

/// De-scrambles (or scrambles) `src` into a newly allocated [`Vec<u8>`] using cyclic 8-byte `key`.
#[must_use]
pub fn descramble_to_vec(src: &[u8], key: [u8; 8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(src.len());
    for (i, &b) in src.iter().enumerate() {
        out.push(b ^ key[i % 8]);
    }
    out
}

